import Image from "next/image";

// Rutinia wordmark (public/brand/rutinia-logo.png, generated by scripts/make-brand.mjs from the owner's source image).
// Transparent background, built for the dark theme. The width/height are the real pixel size so the browser reserves the space (no layout shift).
export function Logo({ className = "h-7 w-auto" }: { className?: string }) {
  return <Image src="/brand/rutinia-logo.png" alt="Rutinia" width={800} height={210} priority className={className} />;
}

/** The "R" with the check on its own (public/brand/rutinia-mark.png). Decorative: the name is announced by the wordmark. */
export function LogoMark({ className = "h-5 w-auto" }: { className?: string }) {
  return <Image src="/brand/rutinia-mark.png" alt="" aria-hidden width={512} height={512} className={className} />;
}
